+      CUTLASS_PRAGMA_UNROLL
+      for (int idx = 0; idx < size(rO); idx += 2) {
+        int row = (idx_in_warpgroup / 32) * 16 + (idx_in_warpgroup % 32 / 4) + (idx % 4 >= 2 ? 8 : 0);
